<?php require "../config.php";$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){try{$s=$pdo->prepare("INSERT INTO users(name,email,phone,password) VALUES(?,?,?,?)");$s->execute([trim($_POST["name"]),trim($_POST["email"]),trim($_POST["phone"]),password_hash($_POST["password"],PASSWORD_DEFAULT)]);$msg="Registration successful. Login now.";}catch(Exception $e){$msg="Email already registered.";}}?><!doctype html><html><head><title>Register</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="form panel"><h2>Citizen Registration</h2><?php if($msg):?><div class="msg"><?=$msg?></div><?php endif;?><form method="post"><input name="name" placeholder="Full Name" required><input type="email" name="email" placeholder="Email" required><input name="phone" placeholder="Phone"><input type="password" name="password" placeholder="Password" required><button class="btn">Register</button></form><a href="login.php">Login</a></div></body></html>